from math import exp
from statistics import median
rho=0.5; tasks=['A','A','B']; Db=[0.,0.,0.]; ell_k=[0.,1.,2.]; ell_b=[1.,1.,1.]
def coords(Dk):
 d=[max(0.,x-y) for x,y in zip(Dk,Db)]; pos=[x for x in d if x>0]; tau=median(pos) if pos else None
 c=[0. if tau is None else 1-exp(-x/tau) for x in d]; h=[0. if x==y==0 else x/(x+y) for x,y in zip(ell_k,ell_b)]
 m=[0. if x==y==0 else (y-x)/(y+x) for x,y in zip(ell_k,ell_b)]; r=[x*y for x,y in zip(c,h)]; return d,tau,c,h,m,r
def gp(r): return [1/len(r)]*len(r) if sum(r)==0 else [(1-rho)/len(r)+rho*x/sum(r) for x in r]
def sp(r):
 out=[0.]*len(r); ts=sorted(set(tasks))
 for t in ts:
  ids=[i for i,v in enumerate(tasks) if v==t]; z=sum(r[i] for i in ids); q=[1/len(ids)]*len(ids) if z==0 else [(1-rho)/len(ids)+rho*r[i]/z for i in ids]
  for i,v in zip(ids,q): out[i]=v/len(ts)
 return out
base=coords([4.,0.,0.]); print('base=',base); print('mechanism=',gp(base[-1]),sp(base[-1])); print('naive=',[1/3]*3,[.25,.25,.5])
pert=coords([4.,1.,0.]); print('perturbed r=',pert[-1]); print('perturbed=',gp(pert[-1]),sp(pert[-1])); print('trace0 deltas=',gp(pert[-1])[0]-1/3,sp(pert[-1])[0]-.25)
print('all-identical c=',coords([0.,0.,0.])[2]); print('single=',gp([0.]))
try: print(0./0.)
except ZeroDivisionError as e: print('zero-IQR=',type(e).__name__)
